const prev = $('Parsear Alerta y Mapear Mantis1').first().json;
const mantisResp = $input.first().json || {};
const issueId = mantisResp.issue?.id || mantisResp.id || 'PENDIENTE';

const emoji = prev.severity === 'critical' ? '🚨' : '⚠️';

const mensaje = `${emoji} *ALERTA DE INFRAESTRUCTURA (ESTÁNDAR) - EXPOJUY 2026*\n\n` +
  `• *Alerta:* \`${prev.alertName}\`\n` +
  `• *Severidad:* \`${prev.severity.toUpperCase()}\`\n` +
  `• *Instancia:* \`${prev.instance}\`\n` +
  `• *Detalle:* ${prev.summary}\n` +
  `• *Ticket Mantis:* #${issueId}\n` +
  `• *Hora:* _${prev.startsAt}_\n\n` +
  `_Esta alerta no corresponde a falla crítica de BD; registrada como incidencia estándar._`;

return [{
  json: {
    ...prev,
    ticketId: issueId,
    telegramText: mensaje
  }
}];

// Normalizador de Alertas de Alertmanager para Mantis, Sub-Workflow RAG y Telegram
const body = $input.first().json.body || $input.first().json;
const alerts = body.alerts || [];

if (alerts.length === 0) {
  return [{
    json: {
      hasAlerts: false,
      message: 'No se recibieron alertas válidas en el payload.'
    }
  }];
}

// Catálogo de alertas que el Asistente RAG de Clúster de BD sabe diagnosticar y resolver
const clusterManagedAlerts = [
  'PostgresPrimaryDown',
  'PostgresReplica1Down',
  'PostgresReplica2Down',
  'PostgresReplicationLagHigh',
  'PostgresHighConnections',
  'ContainerFrequentRestarts'
];

const resultados = alerts.map((alert) => {
  const labels = alert.labels || {};
  const annotations = alert.annotations || {};
  const status = alert.status || body.status || 'firing';

  const alertName = labels.alertname || 'AlertaGeneral';
  const severity = (labels.severity || 'warning').toLowerCase();
  const instance = labels.instance || labels.container || labels.node || 'Servidor Central';
  const node = labels.node || labels.compose_service || instance;
  const summary = annotations.summary || annotations.message || `Anomalía detectada en ${alertName}`;
  const description = annotations.description || 'Sin descripción provista por Prometheus.';

  // Evaluar si es un error que puede manejar el asistente RAG del clúster
  const isClusterManaged = clusterManagedAlerts.includes(alertName) || (alertName.toLowerCase().includes('postgres') && severity === 'critical');

  // Mapeo a Severidad de Mantis Bug Tracker
  let mantisSeverity = 'major';
  let mantisPriority = 'high';

  if (severity === 'critical') {
    mantisSeverity = 'crash';
    mantisPriority = 'urgent';
  } else if (severity === 'warning') {
    mantisSeverity = 'major';
    mantisPriority = 'high';
  }

  const startsAt = alert.startsAt ? new Date(alert.startsAt).toLocaleString('es-AR', { timeZone: 'America/Argentina/Jujuy' }) : new Date().toLocaleString();

  return {
    hasAlerts: true,
    status,
    alertName,
    severity,
    instance,
    node,
    summary,
    description,
    startsAt,
    isClusterManaged,
    mantisSummary: `[PROMETHEUS] ${alertName} en ${instance} (${severity.toUpperCase()})`,
    mantisDescription: `Incidencia detectada automáticamente por Prometheus Alertmanager.\n\n• Métrica/Alerta: ${alertName}\n• Instancia/Nodo: ${node}\n• Severidad: ${severity.toUpperCase()}\n• Resumen: ${summary}\n• Detalle: ${description}\n• Inicio: ${startsAt}\n\nAcción: Derivado a análisis automático.`,
    mantisSeverity,
    mantisPriority
  };
});

return resultados.map(r => ({ json: r }));

